import{_ as a,o as e,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"RAG 原理与边界","description":"弄清 RAG 解决什么、端到端分哪几段、与长上下文/记忆/工具检索如何分工，以及何时不要上高级技巧。","frontmatter":{"title":"RAG 原理与边界","description":"弄清 RAG 解决什么、端到端分哪几段、与长上下文/记忆/工具检索如何分工，以及何时不要上高级技巧。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/knowledge/rag-foundations/rag-principles-boundaries.md","filePath":"ts-ai/knowledge/rag-foundations/rag-principles-boundaries.md","lastUpdated":1786113687000}'),r={name:"ts-ai/knowledge/rag-foundations/rag-principles-boundaries.md"};function s(i,t,o,l,h,p){return e(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="rag-原理与边界" tabindex="-1">RAG 原理与边界 <a class="header-anchor" href="#rag-原理与边界" aria-label="Permalink to &quot;RAG 原理与边界&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>会调 LLM 不等于会做知识库问答。本篇先定问题边界与端到端阶段，再说明和长上下文、记忆、Agent 工具检索怎么分。跑通代码见下一篇 <a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小可运行 RAG</a>。</p><p><strong>目标读者：</strong> 已能调用 ChatModel，尚未系统做过检索增强。<br><strong>前置：</strong> <a href="/ts-ai/foundations/">模型基础</a> 或 <a href="/ts-ai/agent/">Agent 开发</a> 任选其一入门即可。</p><h2 id="_1-rag-解决什么问题" tabindex="-1">1. RAG 解决什么问题 <a class="header-anchor" href="#_1-rag-解决什么问题" aria-label="Permalink to &quot;1. RAG 解决什么问题&quot;">​</a></h2><h3 id="_1-1-定义-检索增强生成" tabindex="-1">1.1 定义：检索增强生成 <a class="header-anchor" href="#_1-1-定义-检索增强生成" aria-label="Permalink to &quot;1.1 定义：检索增强生成&quot;">​</a></h3><p><strong>RAG（Retrieval-Augmented Generation）</strong>：先从受控知识库里<strong>检索</strong>与问题相关的片段，再把片段作为证据交给模型<strong>生成</strong>答案。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户问题</span></span>
<span class="line"><span>  → 检索（召回相关 Chunk）</span></span>
<span class="line"><span>  → 组装上下文（带来源元数据）</span></span>
<span class="line"><span>  → 模型生成（约束：依据上下文作答）</span></span>
<span class="line"><span>  → 返回答案 + 引用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>关键点不是「多塞一点文本」，而是：<strong>回答所依赖的事实来自可审计的检索结果</strong>，而不是只靠模型参数里的记忆。</p><h3 id="_1-2-与「长上下文硬塞」的对比" tabindex="-1">1.2 与「长上下文硬塞」的对比 <a class="header-anchor" href="#_1-2-与「长上下文硬塞」的对比" aria-label="Permalink to &quot;1.2 与「长上下文硬塞」的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>长上下文硬塞</th><th>RAG</th></tr></thead><tbody><tr><td>做法</td><td>把整份/多份材料塞进同一次 Prompt</td><td>按查询召回少量相关片段再生成</td></tr><tr><td>适合规模</td><td>材料少、一次读完</td><td>语料大、持续增长</td></tr><tr><td>主要成本</td><td>Token 与延迟随材料线性涨</td><td>索引建设 + 检索延迟 + 少量生成 Token</td></tr><tr><td>失败样子</td><td>超窗被截断、重要段落被挤掉</td><td>漏召回、错召回、无依据编造</td></tr><tr><td>更新方式</td><td>每次重塞全文</td><td>增量更新索引即可</td></tr></tbody></table><p>材料只有几页、且每次都要通读全文时，硬塞往往更简单。语料以百页/万条 FAQ 计，或需要按租户过滤时，再上 RAG。</p><h3 id="_1-3-与「记忆」的分工" tabindex="-1">1.3 与「记忆」的分工 <a class="header-anchor" href="#_1-3-与「记忆」的分工" aria-label="Permalink to &quot;1.3 与「记忆」的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>RAG</th><th>记忆</th></tr></thead><tbody><tr><td>回答的问题</td><td>知识库里有什么</td><td>这个用户/会话之前怎样</td></tr><tr><td>典型数据</td><td>产品手册、政策、工单知识</td><td>偏好、已确认事实、会话摘要</td></tr><tr><td>写入时机</td><td>文档入库流水线</td><td>对话中提取或用户显式保存</td></tr><tr><td>读出时机</td><td>每次知识问答几乎都检索</td><td>按策略注入（不一定每轮全量）</td></tr></tbody></table><p>同一句「上次退货政策改了」可能既要查知识库（政策正文），又要读记忆（用户上次订单号）。不要用向量库代替会话状态，也不要把用户隐私偏好当公开手册索引。细节见 <a href="/ts-ai/knowledge/memory/">记忆系统</a>。</p><h3 id="_1-4-与「agent-工具检索」的边界" tabindex="-1">1.4 与「Agent 工具检索」的边界 <a class="header-anchor" href="#_1-4-与「agent-工具检索」的边界" aria-label="Permalink to &quot;1.4 与「Agent 工具检索」的边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>固定 RAG 链</th><th>Agent 工具检索</th></tr></thead><tbody><tr><td>控制流</td><td>查询 → 检索 → 生成，步骤固定</td><td>模型决定是否调用检索工具、调几次</td></tr><tr><td>适合</td><td>单一知识库问答、要稳定延迟</td><td>多源、条件分支、先查系统再查文档</td></tr><tr><td>风险</td><td>召回质量</td><td>多跳循环、成本不可控、轨迹难评</td></tr></tbody></table><p>默认先做固定 RAG 链。只有「是否检索、检索哪个源」本身需要模型决策时，再看 <a href="/ts-ai/knowledge/advanced-rag/agentic-rag">Agentic RAG</a> 与 <a href="/ts-ai/agent/runtime/">Agent Runtime</a>。</p><h2 id="_2-端到端链路与阶段" tabindex="-1">2. 端到端链路与阶段 <a class="header-anchor" href="#_2-端到端链路与阶段" aria-label="Permalink to &quot;2. 端到端链路与阶段&quot;">​</a></h2><p>完整 RAG 分三段：<strong>Ingestion（写索引）</strong>、<strong>Query（读索引）</strong>、<strong>Generation（生成）</strong>。高级技巧都挂在某段上，不能代替这三段。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Ingestion]  文件 → 解析 → 清洗 → Chunk → Embedding → 向量库/元数据</span></span>
<span class="line"><span>[Query]      问题 →（可选改写）→ 检索 → 权限过滤 →（可选重排）</span></span>
<span class="line"><span>[Generation] 组装 Prompt → 模型生成 → 附引用 →（可选评测）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_2-1-ingestion-加载-→-清洗-→-chunk-→-embedding-→-入库" tabindex="-1">2.1 Ingestion：加载 → 清洗 → Chunk → Embedding → 入库 <a class="header-anchor" href="#_2-1-ingestion-加载-→-清洗-→-chunk-→-embedding-→-入库" aria-label="Permalink to &quot;2.1 Ingestion：加载 → 清洗 → Chunk → Embedding → 入库&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>产出</th><th>本组后续文章</th></tr></thead><tbody><tr><td>加载与解析</td><td>正文 + 文件级元数据</td><td><a href="/ts-ai/knowledge/document-processing/document-loading-parsing">文件加载与解析</a></td></tr><tr><td>清洗与标准化</td><td>可检索文本 + 权限/来源字段</td><td><a href="/ts-ai/knowledge/document-processing/cleaning-normalization-metadata">清洗、标准化与元数据</a></td></tr><tr><td>Chunk</td><td>带稳定 ID 的片段</td><td><a href="/ts-ai/knowledge/document-processing/chunking-strategies">Chunk 策略</a></td></tr><tr><td>Embedding + 写入</td><td>向量行 + 可过滤元数据</td><td><a href="/ts-ai/knowledge/document-processing/ingestion-pipeline">Ingestion Pipeline</a>、<a href="/ts-ai/knowledge/retrieval/postgresql-pgvector">pgvector</a></td></tr></tbody></table><p>上传 HTTP 入口归 <a href="/ts-ai/backend/api-realtime/file-upload">服务端·文件上传</a>；本模块从「已入队的文档」往后讲。</p><h3 id="_2-2-query-改写-可选-→-检索-→-过滤-→-重排-可选" tabindex="-1">2.2 Query：改写（可选）→ 检索 → 过滤 → 重排（可选） <a class="header-anchor" href="#_2-2-query-改写-可选-→-检索-→-过滤-→-重排-可选" aria-label="Permalink to &quot;2.2 Query：改写（可选）→ 检索 → 过滤 → 重排（可选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>是否必做</th><th>说明</th></tr></thead><tbody><tr><td>查询改写 / 多查询</td><td>可选（进阶）</td><td>问法漂移时再上，见高级 RAG</td></tr><tr><td>相似度检索</td><td><strong>必做</strong></td><td>Top-K 语义或混合召回</td></tr><tr><td>元数据 / 权限过滤</td><td>多租户时 <strong>必做</strong></td><td>过滤应在召回路径上生效，不能只靠 Prompt「别泄露」</td></tr><tr><td>Reranker</td><td>可选</td><td>粗召回后再精排，换质量换延迟</td></tr></tbody></table><h3 id="_2-3-generation-上下文组装-→-生成-→-引用" tabindex="-1">2.3 Generation：上下文组装 → 生成 → 引用 <a class="header-anchor" href="#_2-3-generation-上下文组装-→-生成-→-引用" aria-label="Permalink to &quot;2.3 Generation：上下文组装 → 生成 → 引用&quot;">​</a></h3><p>组装时通常注入：<code>question</code>、排序后的 <code>context</code>、可追溯的 <code>source</code>/<code>chunkId</code>。生成侧应要求「依据不足则明确说不知道」，并让答案能映射回证据。流式与引用时序见 <a href="/ts-ai/knowledge/rag-engineering/">LangChain.js RAG</a>。</p><h3 id="_2-4-各阶段失败时的典型症状" tabindex="-1">2.4 各阶段失败时的典型症状 <a class="header-anchor" href="#_2-4-各阶段失败时的典型症状" aria-label="Permalink to &quot;2.4 各阶段失败时的典型症状&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>优先怀疑阶段</th></tr></thead><tbody><tr><td>解析后正文为空、乱码、缺页</td><td>Ingestion：加载/清洗</td></tr><tr><td>相关段落在库里，却永远召不回</td><td>Query：Chunk 过大/过碎、Embedding 模型不一致、过滤过严</td></tr><tr><td>召回对了，答案却跑题或编造</td><td>Generation：Prompt 约束弱、上下文被截断、未强制引用</td></tr><tr><td>答案引用了用户看不到的文档</td><td>Query：权限过滤缺失或过滤点太晚</td></tr><tr><td>更新文档后仍答旧版</td><td>Ingestion：增量索引 / 生命周期</td></tr></tbody></table><h2 id="_3-核心对象与所有权" tabindex="-1">3. 核心对象与所有权 <a class="header-anchor" href="#_3-核心对象与所有权" aria-label="Permalink to &quot;3. 核心对象与所有权&quot;">​</a></h2><h3 id="_3-1-document-chunk-embedding-retriever" tabindex="-1">3.1 Document / Chunk / Embedding / Retriever <a class="header-anchor" href="#_3-1-document-chunk-embedding-retriever" aria-label="Permalink to &quot;3.1 Document / Chunk / Embedding / Retriever&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对象</th><th>职责</th></tr></thead><tbody><tr><td><strong>Document</strong></td><td>一段可检索文本 + <code>metadata</code>（来源、租户、权限、页码等）</td></tr><tr><td><strong>Chunk</strong></td><td>入库粒度的 Document 片段；应有稳定 ID，便于更新与引用</td></tr><tr><td><strong>Embedding</strong></td><td>把文本变成向量；<strong>写入与查询必须用同一模型与维度</strong></td></tr><tr><td><strong>Retriever</strong></td><td>输入查询，输出 <code>Document[]</code>（或带分数）；屏蔽具体向量库细节</td></tr></tbody></table><p>在 LangChain.js 中，向量库常通过 <code>asRetriever()</code> 变成 Retriever，再接到 RAG Chain。对象契约深讲见 <a href="/ts-ai/knowledge/rag-engineering/documents-retrievers">Document 与 Retriever</a>。</p><h3 id="_3-2-索引侧-vs-查询侧一致性" tabindex="-1">3.2 索引侧 vs 查询侧一致性 <a class="header-anchor" href="#_3-2-索引侧-vs-查询侧一致性" aria-label="Permalink to &quot;3.2 索引侧 vs 查询侧一致性&quot;">​</a></h3><p>下列任一不一致，都会表现为「语义明明相关却召不回」：</p><ul><li>Embedding 模型或维度在写入后被更换，旧向量未重算</li><li>清洗规则只改了查询文本，未重跑 Ingestion</li><li>元数据字段名在过滤与写入时不一致（如 <code>tenant_id</code> vs <code>tenantId</code>）</li><li>权限过滤在应用层「事后扔掉」，导致有效 Top-K 变空却被当成「库里没有」</li></ul><h3 id="_3-3-本模块与别章职责对照" tabindex="-1">3.3 本模块与别章职责对照 <a class="header-anchor" href="#_3-3-本模块与别章职责对照" aria-label="Permalink to &quot;3.3 本模块与别章职责对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>本模块讲</th><th>别章讲</th></tr></thead><tbody><tr><td>Embedding 概念</td><td>检索侧用法与一致性</td><td><a href="/ts-ai/foundations/model/multimodal-tools-embeddings">多模态、工具与 Embedding</a></td></tr><tr><td>文件上传</td><td>Ingestion、索引状态</td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a></td></tr><tr><td>Checkpoint / Store</td><td>记忆语义</td><td><a href="/ts-ai/workflow/durable-execution/checkpoint-store">图持久化：Checkpointer 与 Checkpoint</a></td></tr><tr><td>认证与租户</td><td>检索过滤、记忆隔离</td><td><a href="/ts-ai/quality/security-governance/authentication-authorization">认证与授权</a></td></tr><tr><td>全站评测门禁</td><td>检索/RAG 测法</td><td><a href="/ts-ai/quality/">质量与生产</a></td></tr></tbody></table><h2 id="_4-何时用-何时不用" tabindex="-1">4. 何时用 / 何时不用 <a class="header-anchor" href="#_4-何时用-何时不用" aria-label="Permalink to &quot;4. 何时用 / 何时不用&quot;">​</a></h2><h3 id="_4-1-适合-rag-的场景" tabindex="-1">4.1 适合 RAG 的场景 <a class="header-anchor" href="#_4-1-适合-rag-的场景" aria-label="Permalink to &quot;4.1 适合 RAG 的场景&quot;">​</a></h3><ul><li>答案必须可追溯到内部文档（政策、手册、契约条款）</li><li>语料持续增长，无法每次塞进上下文</li><li>需要按租户、角色或文档 ACL 过滤可见范围</li><li>希望文档更新后尽快反映到回答，而不重新训练模型</li></ul><h3 id="_4-2-不适合或应降级的场景" tabindex="-1">4.2 不适合或应降级的场景 <a class="header-anchor" href="#_4-2-不适合或应降级的场景" aria-label="Permalink to &quot;4.2 不适合或应降级的场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>更合适的做法</th></tr></thead><tbody><tr><td>单次分析一份短 PDF</td><td>长上下文或一次性上传到本次对话</td></tr><tr><td>只要实时订单状态</td><td>工具 / API 查询，不是文档 RAG</td></tr><tr><td>强依赖多跳推理且无评测</td><td>先固定链 + 评测，再考虑 Agentic</td></tr><tr><td>语料极脏、无元数据、无法引用</td><td>先修 Ingestion，不要先上 Reranker</td></tr></tbody></table><h3 id="_4-3-最小闭环判定-能否不配高级技巧先上线" tabindex="-1">4.3 最小闭环判定（能否不配高级技巧先上线） <a class="header-anchor" href="#_4-3-最小闭环判定-能否不配高级技巧先上线" aria-label="Permalink to &quot;4.3 最小闭环判定（能否不配高级技巧先上线）&quot;">​</a></h3><p>若下列都满足，可以先不上查询改写、多步检索、GraphRAG：</p><ol><li>固定语料上，相关问题能稳定召回正确 Chunk</li><li>答案能带上来源，且「库外问题」会拒绝编造</li><li>权限过滤在检索路径生效</li><li>有最小评测集（哪怕几十条）能回归召回与引用</li></ol><p>达不到时，优先修 Chunk、元数据、过滤与 Prompt，而不是加复杂检索图。</p><h2 id="_5-质量与风险边界" tabindex="-1">5. 质量与风险边界 <a class="header-anchor" href="#_5-质量与风险边界" aria-label="Permalink to &quot;5. 质量与风险边界&quot;">​</a></h2><h3 id="_5-1-幻觉、漏召回、错召回" tabindex="-1">5.1 幻觉、漏召回、错召回 <a class="header-anchor" href="#_5-1-幻觉、漏召回、错召回" aria-label="Permalink to &quot;5.1 幻觉、漏召回、错召回&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>含义</th><th>第一刀</th></tr></thead><tbody><tr><td>漏召回</td><td>证据在库里但没进 Top-K</td><td>查 Chunk、Embedding 一致性、过滤</td></tr><tr><td>错召回</td><td>进了上下文的是无关/过期片段</td><td>查元数据、时间字段、重排、去重</td></tr><tr><td>幻觉</td><td>上下文不足仍生成「事实」</td><td>强化「不足则不知」与引用校验</td></tr></tbody></table><p>三者要分开测：只看最终句子对不对，会把检索问题误判成模型问题。</p><h3 id="_5-2-权限与数据泄漏" tabindex="-1">5.2 权限与数据泄漏 <a class="header-anchor" href="#_5-2-权限与数据泄漏" aria-label="Permalink to &quot;5.2 权限与数据泄漏&quot;">​</a></h3><p>多租户系统中，<strong>可见性是检索约束，不是生成礼貌</strong>。过滤应使用入库时写入的租户/ACL 字段，并在测试中证明跨租户查询召不回。记忆侧隔离见 <a href="/ts-ai/knowledge/memory/tenant-permission-isolation">租户与权限隔离</a>。</p><h3 id="_5-3-评测从哪一层开始" tabindex="-1">5.3 评测从哪一层开始 <a class="header-anchor" href="#_5-3-评测从哪一层开始" aria-label="Permalink to &quot;5.3 评测从哪一层开始&quot;">​</a></h3><p>推荐由底向上：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>解析/清洗正确性</span></span>
<span class="line"><span>  → Chunk 可引用性（ID、页码）</span></span>
<span class="line"><span>  → 检索指标（Recall@K 等）</span></span>
<span class="line"><span>  → 带引用的答案正确性</span></span>
<span class="line"><span>  → 权限负例（不该看见的绝不能召回）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>全站回归与门禁放到 <a href="/ts-ai/quality/">质量与生产</a>；本模块内的测法见 <a href="/ts-ai/knowledge/rag-engineering/rag-testing">RAG 测试</a> 与 <a href="/ts-ai/knowledge/retrieval/permission-filtering-retrieval-evaluation">权限过滤与检索评测</a>。</p><h2 id="_6-学习路径与下一篇" tabindex="-1">6. 学习路径与下一篇 <a class="header-anchor" href="#_6-学习路径与下一篇" aria-label="Permalink to &quot;6. 学习路径与下一篇&quot;">​</a></h2><h3 id="_6-1-本篇之后读什么" tabindex="-1">6.1 本篇之后读什么 <a class="header-anchor" href="#_6-1-本篇之后读什么" aria-label="Permalink to &quot;6.1 本篇之后读什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本篇（边界与阶段）</span></span>
<span class="line"><span>  → 最小可运行 RAG（固定语料跑通）</span></span>
<span class="line"><span>  → 文档处理 → 检索系统 → LangChain.js RAG</span></span>
<span class="line"><span>  → 记忆系统 → 组装配方与自检</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_6-2-高级-rag-何时再碰" tabindex="-1">6.2 高级 RAG 何时再碰 <a class="header-anchor" href="#_6-2-高级-rag-何时再碰" aria-label="Permalink to &quot;6.2 高级 RAG 何时再碰&quot;">​</a></h3><p><a href="/ts-ai/knowledge/advanced-rag/">高级 RAG</a> 标为<strong>进阶</strong>。仅在最小闭环已通过、且评测证明「单次 Top-K 不够」时再引入查询改写、多步或 Agentic。不要用 GraphRAG 掩盖脏数据和缺失权限模型。</p><p>下一篇：<a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小可运行 RAG</a>。</p>`,64)])])}const u=a(r,[["render",s]]);export{b as __pageData,u as default};
